    , t.charge= #{charge}


    , t.lon= #{lon}



    , t.machine_name= #{machineName}


    , t.pos_upload_sec= #{posUploadSec}


    , t.staff_name= #{staffName}


    , t.staff_id= #{staffId}


    , t.lat= #{lat}

where 1=1

    and t.machine_id= #{machineId}


    and t.store_id= #{storeId}

